{"type": "FUNCTION", "name": "finish_expansion_stmt", "location": "/data/zhangtianrong/projects/rustc-cbi/graphlocator_gcc/gcc/gcc/cp/pt.cc", "content": "/* Finish an expansion-statement.  */

void
finish_expansion_stmt (tree expansion_stmt, tree args,
		       tsubst_flags_t complain, tree in_decl)
{
  tree expansion_init = TEMPLATE_FOR_EXPR (expansion_stmt);
  if (error_operand_p (expansion_init))
    return;

  enum expansion_stmt_kind {
    esk_none,
    esk_iterating,
    esk_destructuring,
    esk_enumerating
  } kind = esk_none;

  unsigned HOST_WIDE_INT n = 0;
  tree range_decl = TEMPLATE_FOR_DECL (expansion_stmt);
  bool is_decomp = false;
  if (TREE_CODE (range_decl) == TREE_VEC)
    {
      is_decomp = true;
      range_decl = TREE_VEC_ELT (range_decl, 0);
    }
  if (error_operand_p (range_decl))
    return;

  location_t loc = DECL_SOURCE_LOCATION (range_decl);
  tree begin = NULL_TREE;
  auto_vec<tree, 8> destruct_decls;
  if (BRACE_ENCLOSED_INITIALIZER_P (expansion_init))
    {
      /* Enumerating expansion statements.  */
      kind = esk_enumerating;
      n = CONSTRUCTOR_NELTS (expansion_init);
    }
  else if (TYPE_REF_P (TREE_TYPE (expansion_init))
	   ? TREE_CODE (TREE_TYPE (TREE_TYPE (expansion_init))) != ARRAY_TYPE
	   : TREE_CODE (TREE_TYPE (expansion_init)) != ARRAY_TYPE)
    {
      tree range_temp, begin_expr, end_expr, iter_type;
      range_temp = convert_from_reference (build_range_temp (expansion_init));
      iter_type = cp_perform_range_for_lookup (range_temp, &begin_expr,
					       &end_expr, tf_none);
      if (begin_expr != error_mark_node && end_expr != error_mark_node)
	{
	  kind = esk_iterating;
	  gcc_assert (iter_type);
	}
    }
  if (kind == esk_iterating)
    {
      /* Iterating expansion statements.  */
      tree end;
      begin = cp_build_range_for_decls (loc, expansion_init, &end, true);
      if (!error_operand_p (begin) && !error_operand_p (end))
	{
	  tree i = get_target_expr (begin);
	  tree w = build_stmt (loc, WHILE_STMT, NULL_TREE, NULL_TREE,
			       NULL_TREE, NULL_TREE, NULL_TREE);
	  tree r = get_target_expr (build_zero_cst (ptrdiff_type_node));
	  tree iinc = build_x_unary_op (loc, PREINCREMENT_EXPR,
					TARGET_EXPR_SLOT (i), NULL_TREE,
					tf_warning_or_error);
	  tree rinc = build2 (PREINCREMENT_EXPR, ptrdiff_type_node,
			      TARGET_EXPR_SLOT (r),
			      build_int_cst (ptrdiff_type_node, 1));
	  WHILE_BODY (w) = build_compound_expr (loc, iinc, rinc);
	  WHILE_COND (w) = build_x_binary_op (loc, NE_EXPR, i, ERROR_MARK,
					      end, ERROR_MARK, NULL_TREE, NULL,
					      tf_warning_or_error);
	  tree e = build_compound_expr (loc, r, i);
	  e = build_compound_expr (loc, e, w);
	  e = build_compound_expr (loc, e, TARGET_EXPR_SLOT (r));
	  e = cxx_constant_value (e);
	  if (tree_fits_uhwi_p (e))
	    n = tree_to_uhwi (e);
	}
    }
  else if (kind == esk_none)
    {
      kind = esk_destructuring;
      HOST_WIDE_INT sz = cp_decomp_size (loc, TREE_TYPE (expansion_init),
					 tf_warning_or_error);
      if (sz < 0)
	return;
      n = sz;
      tree auto_node = make_auto ();
      tree decomp_type = cp_build_reference_type (auto_node, true);
      decomp_type = do_auto_deduction (decomp_type, expansion_init, auto_node);
      tree decl = build_decl (loc, VAR_DECL, NULL_TREE, decomp_type);
      TREE_USED (decl) = 1;
      DECL_ARTIFICIAL (decl) = 1;
      DECL_DECLARED_CONSTEXPR_P (decl)
	= DECL_DECLARED_CONSTEXPR_P (range_decl);
      if (DECL_DECLARED_CONSTEXPR_P (decl))
	TREE_READONLY (decl) = 1;
      if (n)
	fit_decomposition_lang_decl (decl, NULL_TREE);
      pushdecl (decl);
      cp_decomp this_decomp;
      this_decomp.count = n;
      destruct_decls.safe_grow (n, true);
      for (unsigned HOST_WIDE_INT i = 0; i < n; ++i)
	{
	  tree this_decl = build_decl (loc, VAR_DECL, NULL_TREE, make_auto ());
	  TREE_USED (this_decl) = 1;
	  DECL_ARTIFICIAL (this_decl) = 1;
	  DECL_DECLARED_CONSTEXPR_P (this_decl)
	    = DECL_DECLARED_CONSTEXPR_P (decl);
	  if (DECL_DECLARED_CONSTEXPR_P (decl))
	    TREE_READONLY (this_decl) = 1;
	  pushdecl (this_decl);
	  this_decomp.decl = this_decl;
	  destruct_decls[i] = this_decl;
	}
      DECL_NAME (decl) = for_range__identifier;
      cp_finish_decl (decl, expansion_init,
		      /*is_constant_init*/false, NULL_TREE,
		      LOOKUP_ONLYCONVERTING, n ? &this_decomp : NULL);
      DECL_NAME (decl) = NULL_TREE;
    }

  expansion_stmt_bc bc_data = { NULL_TREE, NULL_TREE, NULL, loc, false };

  for (unsigned HOST_WIDE_INT i = 0; i < n; ++i)
    {
      tree scope = do_pushlevel (sk_block);
      bool revert_outer
	= (current_binding_level->level_chain
	   && current_binding_level->level_chain->kind == sk_template_for);
      /* Don't diagnose redeclaration of for-range-declaration decls.
	 The sk_template_for block is reused for the originally parsed
	 source as well as the lowered one.  In the original one
	 redeclaration of the for-range-declaration decls in the substatement
	 should be diagnosed (i.e. declarations of the same name in sk_block
	 of the body vs. declarations in sk_template_for block).  In the
	 lowered case, the sk_block added by do_pushlevel (sk_block) above
	 will be block in the lowering of each Si.  Those blocks do redeclare
	 for-range-declaration, so temporarily change sk_template_for
	 kind to sk_block to avoid it being diagnosed as invalid.  */
      if (revert_outer)
	current_binding_level->level_chain->kind = sk_block;
      tree type = TREE_TYPE (range_decl);
      if (args)
	type = tsubst (type, args, complain | tf_tst_ok, in_decl);
      tree decl = build_decl (loc, VAR_DECL, DECL_NAME (range_decl), type);
      DECL_ATTRIBUTES (decl) = DECL_ATTRIBUTES (range_decl);
      if (args)
	apply_late_template_attributes (&decl, DECL_ATTRIBUTES (decl),
					/*flags=*/0, args, complain,
					in_decl);

      DECL_DECLARED_CONSTEXPR_P (decl)
	= DECL_DECLARED_CONSTEXPR_P (range_decl);
      if (DECL_DECLARED_CONSTEXPR_P (decl))
	TREE_READONLY (decl) = 1;
      pushdecl (decl);
      tree init = NULL_TREE;
      switch (kind)
	{
	case esk_enumerating:
	  init = CONSTRUCTOR_ELT (expansion_init, i)->value;
	  break;
	case esk_iterating:
	  tree iter_init, auto_node, iter_type, iter;
	  iter_init
	    = build_x_binary_op (loc, PLUS_EXPR, begin, ERROR_MARK,
				 build_int_cst (ptrdiff_type_node, i),
				 ERROR_MARK, NULL_TREE, NULL,
				 tf_warning_or_error);
	  auto_node = make_auto ();
	  iter_type = do_auto_deduction (auto_node, iter_init, auto_node);
	  iter = build_decl (loc, VAR_DECL, NULL_TREE, iter_type);
	  TREE_USED (iter) = 1;
	  DECL_ARTIFICIAL (iter) = 1;
	  TREE_STATIC (iter) = 1;
	  DECL_DECLARED_CONSTEXPR_P (iter) = 1;
	  pushdecl (iter);
	  cp_finish_decl (iter, iter_init, /*is_constant_init*/false,
			  NULL_TREE, LOOKUP_ONLYCONVERTING);
	  init = build_x_indirect_ref (loc, iter, RO_UNARY_STAR, NULL_TREE,
				       tf_warning_or_error);
	  break;
	case esk_destructuring:
	  init = convert_from_reference (destruct_decls[i]);
	  break;
	default:
	  gcc_unreachable ();
	}
      cp_decomp this_decomp = {};
      if (is_decomp)
	{
	  fit_decomposition_lang_decl (decl, NULL_TREE);
	  tree v = TEMPLATE_FOR_DECL (expansion_stmt);
	  this_decomp.count = TREE_VEC_LENGTH (v) - 1;
	  for (unsigned i = 0; i < this_decomp.count; ++i)
	    {
	      tree this_decl
		= build_decl (loc, VAR_DECL,
			      DECL_NAME (TREE_VEC_ELT (v, i + 1)),
			      make_auto ());
	      TREE_USED (this_decl) = 1;
	      DECL_ARTIFICIAL (this_decl) = 1;
	      DECL_ATTRIBUTES (this_decl)
		= DECL_ATTRIBUTES (TREE_VEC_ELT (v, i + 1));
	      if (DECL_PACK_P (TREE_VEC_ELT (v, i + 1)))
		{
		  tree dtype = cxx_make_type (DECLTYPE_TYPE);
		  DECLTYPE_TYPE_EXPR (dtype) = this_decl;
		  DECLTYPE_TYPE_ID_EXPR_OR_MEMBER_ACCESS_P (dtype) = 1;
		  SET_TYPE_STRUCTURAL_EQUALITY (dtype);
		  tree type = cxx_make_type (TYPE_PACK_EXPANSION);
		  PACK_EXPANSION_PATTERN (type) = dtype;
		  SET_TYPE_STRUCTURAL_EQUALITY (type);
		  PACK_EXPANSION_PARAMETER_PACKS (type) = this_decl;
		  TREE_TYPE (this_decl) = type;
		}
	      if (args)
		apply_late_template_attributes (&this_decl,
						DECL_ATTRIBUTES (this_decl),
						/*flags=*/0, args,
						complain, in_decl);
	      DECL_DECLARED_CONSTEXPR_P (this_decl)
		= DECL_DECLARED_CONSTEXPR_P (decl);
	      if (DECL_DECLARED_CONSTEXPR_P (decl))
		TREE_READONLY (this_decl) = 1;
	      pushdecl (this_decl);
	      this_decomp.decl = this_decl;
	    }
	}
      cp_finish_decl (decl, init, false, NULL_TREE,
		      LOOKUP_ONLYCONVERTING, is_decomp ? &this_decomp : NULL);
      if (revert_outer)
	current_binding_level->level_chain->kind = sk_template_for;
      tree targs = args;
      if (args == NULL_TREE)
	{
	  targs = make_tree_vec (1);
	  TREE_VEC_ELT (targs, 0) = build_int_cst (ptrdiff_type_node, i + 1);
	}
      if (args != NULL_TREE
	  || push_tinst_level_loc (expansion_stmt, targs, loc))
	{
	  local_specialization_stack lss (lss_copy);
	  register_local_specialization (decl, range_decl);
	  if (is_decomp)
	    {
	      tree d = this_decomp.decl;
	      unsigned int cnt = this_decomp.count;
	      tree v = TEMPLATE_FOR_DECL (expansion_stmt);
	      for (unsigned int i = 0; i < cnt; ++i, d = DECL_CHAIN (d))
		register_local_specialization (d, TREE_VEC_ELT (v, cnt - i));
	    }
	  tsubst_stmt (TEMPLATE_FOR_BODY (expansion_stmt),
		       targs, complain, in_decl ? in_decl : range_decl);
	  if (args == NULL_TREE)
	    pop_tinst_level ();
	}
      tree stmt = do_poplevel (scope);
      if (stmt)
	{
	  add_stmt (stmt);
	  hash_set<tree> pset;
	  bc_data.continue_label = NULL_TREE;
	  bc_data.pset = &pset;
	  cp_walk_tree (&stmt, expansion_stmt_find_bc_r, &bc_data, &pset);
	  if (bc_data.continue_label)
	    add_stmt (build1 (LABEL_EXPR, void_type_node,
			      bc_data.continue_label));
	}
    }
  if (bc_data.break_label)
    add_stmt (build1 (LABEL_EXPR, void_type_node, bc_data.break_label));
  if (args == NULL_TREE)
    {
      TREE_TYPE (range_decl) = error_mark_node;
      if (DECL_HAS_VALUE_EXPR_P (range_decl))
	{
	  SET_DECL_VALUE_EXPR (range_decl, NULL_TREE);
	  DECL_HAS_VALUE_EXPR_P (range_decl) = 0;
	}
      if (is_decomp)
	{
	  tree v = TEMPLATE_FOR_DECL (expansion_stmt);
	  for (int i = 1; i < TREE_VEC_LENGTH (v); ++i)
	    {
	      tree d = TREE_VEC_ELT (v, i);
	      TREE_TYPE (d) = error_mark_node;
	      if (DECL_HAS_VALUE_EXPR_P (d))
		{
		  SET_DECL_VALUE_EXPR (d, NULL_TREE);
		  DECL_HAS_VALUE_EXPR_P (d) = 0;
		}
	    }
	}"}

{"type": "FUNCTION", "name": "tsubst_expr", "location": "/data/zhangtianrong/projects/rustc-cbi/graphlocator_gcc/gcc/gcc/cp/pt.cc", "content": "tree
tsubst_expr (tree t, tree args, tsubst_flags_t complain, tree in_decl)
{
#define RETURN(EXP) do { retval = (EXP); goto out; } while(0)
#define RECUR(NODE)						\
  tsubst_expr (NODE, args, complain, in_decl)

  tree retval, op1;
  location_t save_loc;

  if (t == NULL_TREE || t == error_mark_node)
    return t;

  save_loc = input_location;
  if (location_t eloc = cp_expr_location (t))
    input_location = eloc;

  /* N3276 decltype magic only applies to calls at the top level or on the
     right side of a comma.  */
  tsubst_flags_t decltype_flag = (complain & tf_decltype);
  complain &= ~tf_decltype;

  /* This flag only applies to id-expressions at the top level, and
     controls resolution thereof.  */
  tsubst_flags_t no_name_lookup_flag = (complain & tf_no_name_lookup);
  complain &= ~tf_no_name_lookup;

  if (!no_name_lookup_flag)
    if (tree d = maybe_dependent_member_ref (t, args, complain, in_decl))
      return d;

  switch (TREE_CODE (t))
    {
    case USING_DECL:
      t = DECL_NAME (t);
      /* Fall through.  */
    case IDENTIFIER_NODE:
      {
	tree decl;
	cp_id_kind idk;
	const char *error_msg;

	if (IDENTIFIER_CONV_OP_P (t))
	  {
	    tree new_type = tsubst (TREE_TYPE (t), args, complain, in_decl);
	    t = make_conv_op_name (new_type);
	  }

	if (no_name_lookup_flag)
	  RETURN (t);

	/* Look up the name.  */
	decl = lookup_name (t);

	/* By convention, expressions use ERROR_MARK_NODE to indicate
	   failure, not NULL_TREE.  */
	if (decl == NULL_TREE)
	  decl = error_mark_node;

	decl = finish_id_expression (t, decl, NULL_TREE,
				     &idk,
				     /*i_c_e_p=*/false,
				     /*allow_i_c_e_p=*/true,
				     /*non_i_c_e_p=*/nullptr,
				     /*template_p=*/false,
				     /*done=*/true,
				     /*address_p=*/false,
				     /*template_arg_p=*/false,
				     &error_msg,
				     input_location);
	if (error_msg)
	  error (error_msg);
	if (identifier_p (decl))
	  {
	    if (complain & tf_error)
	      unqualified_name_lookup_error (decl);
	    decl = error_mark_node;
	  }
	RETURN (decl);
      }

    case TEMPLATE_ID_EXPR:
      {
	tree object;
	tree templ = TREE_OPERAND (t, 0);
	tree targs = TREE_OPERAND (t, 1);

	if (no_name_lookup_flag)
	  templ = tsubst_name (templ, args, complain, in_decl);
	else
	  templ = tsubst_expr (templ, args, complain, in_decl);

	if (targs)
	  targs = tsubst_template_args (targs, args, complain, in_decl);
	if (targs == error_mark_node)
	  RETURN (error_mark_node);

	if (TREE_CODE (templ) == SCOPE_REF)
	  {
	    tree name = TREE_OPERAND (templ, 1);
	    tree tid = lookup_template_function (name, targs);
	    TREE_OPERAND (templ, 1) = tid;
	    RETURN (templ);
	  }

	if (concept_definition_p (templ))
	  {
	    tree check = build_concept_check (templ, targs, complain);
	    if (check == error_mark_node)
	      RETURN (error_mark_node);
	    RETURN (check);
	  }

	if (variable_template_p (templ))
	  {
	    if (no_name_lookup_flag)
	      RETURN (lookup_template_variable (templ, targs, complain));

	    tree r = lookup_and_finish_template_variable (templ, targs,
							  complain);
	    r = convert_from_reference (r);
	    r = maybe_wrap_with_location (r, EXPR_LOCATION (t));
	    RETURN (r);
	  }

	if (TREE_CODE (templ) == COMPONENT_REF)
	  {
	    object = TREE_OPERAND (templ, 0);
	    templ = TREE_OPERAND (templ, 1);
	  }
	else
	  object = NULL_TREE;

	tree tid = lookup_template_function (templ, targs);
	protected_set_expr_location (tid, EXPR_LOCATION (t));

	if (object)
	  RETURN (build3 (COMPONENT_REF, TREE_TYPE (tid),
			 object, tid, NULL_TREE));
	else if (no_name_lookup_flag)
	  RETURN (tid);
	else if (identifier_p (templ))
	  {
	    /* C++20 P0846: we can encounter an IDENTIFIER_NODE here when
	       name lookup found nothing when parsing the template name.  */
	    gcc_assert (cxx_dialect >= cxx20 || seen_error ());
	    RETURN (tid);
	  }
	else
	  RETURN (baselink_for_fns (tid));
      }

    case INDIRECT_REF:
      {
	tree r = RECUR (TREE_OPERAND (t, 0));

	if (REFERENCE_REF_P (t))
	  {
	    /* A type conversion to reference type will be enclosed in
	       such an indirect ref, but the substitution of the cast
	       will have also added such an indirect ref.  */
	    r = convert_from_reference (r);
	  }
	else
	  r = build_x_indirect_ref (input_location, r, RO_UNARY_STAR,
				    templated_operator_saved_lookups (t),
				    complain|decltype_flag);

	if (REF_PARENTHESIZED_P (t))
	  r = force_paren_expr (r);

	RETURN (r);
      }

    case MEM_REF:
      {
	tree op0 = RECUR (TREE_OPERAND (t, 0));
	tree op1 = RECUR (TREE_OPERAND (t, 0));
	tree new_type = tsubst (TREE_TYPE (t), args, complain, in_decl);
	RETURN (build2_loc (EXPR_LOCATION (t), MEM_REF, new_type, op0, op1));
      }

    case NOP_EXPR:
      {
	tree type = tsubst (TREE_TYPE (t), args, complain, in_decl);
	tree op0 = RECUR (TREE_OPERAND (t, 0));
	RETURN (build_nop (type, op0));
      }

    case IMPLICIT_CONV_EXPR:
      {
	tree type = tsubst (TREE_TYPE (t), args, complain, in_decl);
	if (type == error_mark_node)
	  RETURN (error_mark_node);
	tree expr = RECUR (TREE_OPERAND (t, 0));
	if (dependent_type_p (type) || type_dependent_expression_p (expr))
	  {
	    retval = copy_node (t);
	    TREE_TYPE (retval) = type;
	    TREE_OPERAND (retval, 0) = expr;
	    RETURN (retval);
	  }
	if (IMPLICIT_CONV_EXPR_NONTYPE_ARG (t))
	  {
	    tree r = convert_nontype_argument (type, expr, complain);
	    if (r == NULL_TREE)
	      r = error_mark_node;
	    RETURN (r);
	  }
	int flags = LOOKUP_IMPLICIT;
	if (IMPLICIT_CONV_EXPR_DIRECT_INIT (t))
	  flags = LOOKUP_NORMAL;
	if (IMPLICIT_CONV_EXPR_BRACED_INIT (t))
	  flags |= LOOKUP_NO_NARROWING;
	RETURN (perform_implicit_conversion_flags (type, expr, complain,
						  flags));
      }

    case CONVERT_EXPR:
      {
	tree type = tsubst (TREE_TYPE (t), args, complain, in_decl);
	tree op0 = RECUR (TREE_OPERAND (t, 0));
	if (op0 == error_mark_node)
	  RETURN (error_mark_node);
	RETURN (build1 (CONVERT_EXPR, type, op0));
      }

    case CAST_EXPR:
    case REINTERPRET_CAST_EXPR:
    case CONST_CAST_EXPR:
    case DYNAMIC_CAST_EXPR:
    case STATIC_CAST_EXPR:
      {
	tree type;
	tree op, r = NULL_TREE;

	tsubst_flags_t tcomplain = complain;
	if (TREE_CODE (t) == CAST_EXPR)
	  tcomplain |= tf_tst_ok;
	type = tsubst (TREE_TYPE (t), args, tcomplain, in_decl);

	op = RECUR (TREE_OPERAND (t, 0));

	warning_sentinel s(warn_useless_cast);
	warning_sentinel s2(warn_ignored_qualifiers);
	warning_sentinel s3(warn_int_in_bool_context);
	switch (TREE_CODE (t))
	  {
	  case CAST_EXPR:
	    r = build_functional_cast (input_location, type, op, complain);
	    break;
	  case REINTERPRET_CAST_EXPR:
	    r = build_reinterpret_cast (input_location, type, op, complain);
	    break;
	  case CONST_CAST_EXPR:
	    r = build_const_cast (input_location, type, op, complain);
	    break;
	  case DYNAMIC_CAST_EXPR:
	    r = build_dynamic_cast (input_location, type, op, complain);
	    break;
	  case STATIC_CAST_EXPR:
	    r = build_static_cast (input_location, type, op, complain);
	    if (IMPLICIT_RVALUE_P (t))
	      set_implicit_rvalue_p (r);
	    break;
	  default:
	    gcc_unreachable ();
	  }

	RETURN (r);
      }

    case BIT_CAST_EXPR:
      {
	tree type = tsubst (TREE_TYPE (t), args, complain, in_decl);
	tree op0 = RECUR (TREE_OPERAND (t, 0));
	RETURN (cp_build_bit_cast (EXPR_LOCATION (t), type, op0, complain));
      }

    case POSTDECREMENT_EXPR:
    case POSTINCREMENT_EXPR:
      op1 = tsubst_non_call_postfix_expression (TREE_OPERAND (t, 0),
						args, complain, in_decl);
      RETURN (build_x_unary_op (input_location, TREE_CODE (t), op1,
				templated_operator_saved_lookups (t),
				complain|decltype_flag));

    case BIT_NOT_EXPR:
      if (identifier_p (TREE_OPERAND (t, 0)))
	{
	  gcc_checking_assert (no_name_lookup_flag);
	  RETURN (t);
	}
      else if (TYPE_P (TREE_OPERAND (t, 0)))
	{
	  gcc_checking_assert (no_name_lookup_flag);
	  tree op0 = tsubst (TREE_OPERAND (t, 0), args, complain, in_decl);
	  RETURN (build_min_nt_loc (EXPR_LOCATION (t), BIT_NOT_EXPR, op0));
	}
      /* Fall through.  */
    case PREDECREMENT_EXPR:
    case PREINCREMENT_EXPR:
    case NEGATE_EXPR:
    case ABS_EXPR:
    case TRUTH_NOT_EXPR:
    case UNARY_PLUS_EXPR:  /* Unary + */
    case REALPART_EXPR:
    case IMAGPART_EXPR:
      RETURN (build_x_unary_op (input_location, TREE_CODE (t),
				RECUR (TREE_OPERAND (t, 0)),
				templated_operator_saved_lookups (t),
				complain|decltype_flag));

    case EXCESS_PRECISION_EXPR:
      {
	tree type = tsubst (TREE_TYPE (t), args, complain, in_decl);
	tree op0 = RECUR (TREE_OPERAND (t, 0));
	if (TREE_CODE (op0) == EXCESS_PRECISION_EXPR)
	  RETURN (op0);
	RETURN (build1_loc (EXPR_LOCATION (t), EXCESS_PRECISION_EXPR,
			    type, op0));
      }

    case FIX_TRUNC_EXPR:
      /* convert_like should have created an IMPLICIT_CONV_EXPR.  */
      gcc_unreachable ();

    case ADDR_EXPR:
      op1 = TREE_OPERAND (t, 0);
      if (TREE_CODE (op1) == LABEL_DECL)
	RETURN (finish_label_address_expr (DECL_NAME (op1),
					  EXPR_LOCATION (op1)));
      if (TREE_CODE (op1) == SCOPE_REF)
	op1 = tsubst_qualified_id (op1, args, complain, in_decl,
				   /*done=*/true, /*address_p=*/true);
      else
	op1 = tsubst_non_call_postfix_expression (op1, args, complain,
						  in_decl);
      RETURN (build_x_unary_op (input_location, ADDR_EXPR, op1,
				templated_operator_saved_lookups (t),
				complain|decltype_flag));

    case PLUS_EXPR:
    case MINUS_EXPR:
    case MULT_EXPR:
    case TRUNC_DIV_EXPR:
    case CEIL_DIV_EXPR:
    case FLOOR_DIV_EXPR:
    case ROUND_DIV_EXPR:
    case EXACT_DIV_EXPR:
    case BIT_AND_EXPR:
    case BIT_IOR_EXPR:
    case BIT_XOR_EXPR:
    case TRUNC_MOD_EXPR:
    case FLOOR_MOD_EXPR:
    case TRUTH_ANDIF_EXPR:
    case TRUTH_ORIF_EXPR:
    case TRUTH_AND_EXPR:
    case TRUTH_OR_EXPR:
    case RSHIFT_EXPR:
    case LSHIFT_EXPR:
    case EQ_EXPR:
    case NE_EXPR:
    case MAX_EXPR:
    case MIN_EXPR:
    case LE_EXPR:
    case GE_EXPR:
    case LT_EXPR:
    case GT_EXPR:
    case SPACESHIP_EXPR:
    case MEMBER_REF:
    case DOTSTAR_EXPR:
      {
	/* If either OP0 or OP1 was value- or type-dependent, suppress
	   warnings that depend on the range of the types involved.  */
	tree op0 = TREE_OPERAND (t, 0);
	tree op1 = TREE_OPERAND (t, 1);
	const bool was_dep = (dependent_operand_p (op0)
			      || dependent_operand_p (op1));
	op0 = RECUR (op0);
	op1 = RECUR (op1);

	warning_sentinel s1(warn_type_limits, was_dep);
	warning_sentinel s2(warn_div_by_zero, was_dep);
	warning_sentinel s3(warn_logical_op, was_dep);
	warning_sentinel s4(warn_tautological_compare, was_dep);
	warning_sentinel s5(warn_address, was_dep);

	tree r = build_x_binary_op
	  (input_location, TREE_CODE (t),
	   op0,
	   (warning_suppressed_p (TREE_OPERAND (t, 0))
	    ? ERROR_MARK
	    : TREE_CODE (TREE_OPERAND (t, 0))),
	   op1,
	   (warning_suppressed_p (TREE_OPERAND (t, 1))
	    ? ERROR_MARK
	    : TREE_CODE (TREE_OPERAND (t, 1))),
	   templated_operator_saved_lookups (t),
	   /*overload=*/NULL,
	   complain|decltype_flag);
	if (EXPR_P (r))
	  copy_warning (r, t);

	RETURN (r);
      }

    case POINTER_PLUS_EXPR:
      {
	tree op0 = RECUR (TREE_OPERAND (t, 0));
	if (op0 == error_mark_node)
	  RETURN (error_mark_node);
	tree op1 = RECUR (TREE_OPERAND (t, 1));
	if (op1 == error_mark_node)
	  RETURN (error_mark_node);
	RETURN (fold_build_pointer_plus (op0, op1));
      }

    case SCOPE_REF:
      if (no_name_lookup_flag)
	{
	  tree op0 = tsubst_scope (TREE_OPERAND (t, 0), args, complain, in_decl);
	  tree op1 = tsubst_name (TREE_OPERAND (t, 1), args, complain, in_decl);
	  RETURN (build_qualified_name (/*type=*/NULL_TREE, op0, op1,
					QUALIFIED_NAME_IS_TEMPLATE (t)));
	}
      else
	RETURN (tsubst_qualified_id (t, args, complain, in_decl, /*done=*/true,
				    /*address_p=*/false));

    case BASELINK:
      RETURN (tsubst_baselink (t, current_nonlambda_class_type (),
			       args, complain, in_decl));

    case ARRAY_REF:
      op1 = tsubst_non_call_postfix_expression (TREE_OPERAND (t, 0),
						args, complain, in_decl);
      if (TREE_CODE (TREE_OPERAND (t, 1)) == CALL_EXPR
	  && (CALL_EXPR_FN (TREE_OPERAND (t, 1))
	      == ovl_op_identifier (ARRAY_REF)))
	{
	  tree c = TREE_OPERAND (t, 1);
	  releasing_vec index_exp_list;
	  tsubst_call_args (c, args, complain, in_decl, index_exp_list);

	  tree r;
	  if (vec_safe_length (index_exp_list) == 1
	      && !PACK_EXPANSION_P (index_exp_list[0]))
	    r = grok_array_decl (EXPR_LOCATION (t), op1,
				 index_exp_list[0], NULL,
				 complain | decltype_flag);
	  else
	    r = grok_array_decl (EXPR_LOCATION (t), op1,
				 NULL_TREE, &index_exp_list,
				 complain | decltype_flag);
	  RETURN (r);
	}
      RETURN (build_x_array_ref (EXPR_LOCATION (t), op1,
				 RECUR (TREE_OPERAND (t, 1)),
				 complain|decltype_flag));

    case OMP_ARRAY_SECTION:
      {
	tree op0 = RECUR (TREE_OPERAND (t, 0));
	tree op1 = NULL_TREE, op2 = NULL_TREE;
	if (op0 == error_mark_node)
	  RETURN (error_mark_node);
	if (TREE_OPERAND (t, 1))
	  {
	    op1 = RECUR (TREE_OPERAND (t, 1));
	    if (op1 == error_mark_node)
	      RETURN (error_mark_node);
	  }
	if (TREE_OPERAND (t, 2))
	  {
	    op2 = RECUR (TREE_OPERAND (t, 2));
	    if (op2 == error_mark_node)
	      RETURN (error_mark_node);
	  }
	RETURN (build_omp_array_section (EXPR_LOCATION (t), op0, op1, op2));
      }

    case OMP_DECLARE_MAPPER:
      {
	t = copy_node (t);

	tree decl = OMP_DECLARE_MAPPER_DECL (t);
	DECL_OMP_DECLARE_MAPPER_P (decl) = 1;
	decl = tsubst (decl, args, complain, in_decl);
	tree type = tsubst (TREE_TYPE (t), args, complain, in_decl);
	tree clauses = OMP_DECLARE_MAPPER_CLAUSES (t);
	clauses = tsubst_omp_clauses (clauses, C_ORT_OMP_DECLARE_MAPPER, args,
				      complain, in_decl);
	TREE_TYPE (t) = type;
	OMP_DECLARE_MAPPER_DECL (t) = decl;
	OMP_DECLARE_MAPPER_CLAUSES (t) = clauses;
	RETURN (t);
      }

    case SIZEOF_EXPR:
      if (PACK_EXPANSION_P (TREE_OPERAND (t, 0))
	  || ARGUMENT_PACK_P (TREE_OPERAND (t, 0)))
	{
	  tree expanded, op = TREE_OPERAND (t, 0);
	  int len = 0;

	  if (SIZEOF_EXPR_TYPE_P (t))
	    op = TREE_TYPE (op);

	  ++cp_unevaluated_operand;
	  ++c_inhibit_evaluation_warnings;
	  /* We only want to compute the number of arguments.  */
	  if (PACK_EXPANSION_P (op))
	    {
	      expanded = NULL_TREE;
	      if (DECL_DECOMPOSITION_P (PACK_EXPANSION_PATTERN (op)))
		{
		  tree d = PACK_EXPANSION_PATTERN (op);
		  if (DECL_HAS_VALUE_EXPR_P (d))
		    {
		      d = DECL_VALUE_EXPR (d);
		      if (TREE_CODE (d) == TREE_VEC)
			{
			  tree b = TREE_VEC_ELT (d, 0);
			  if (!type_dependent_expression_p_push (b))
			    {
			      expanded = void_node;
			      len = TREE_VEC_LENGTH (d) - 2;
			    }
			}
		    }
		}
	      if (!expanded)
		expanded = tsubst_pack_expansion (op, args, complain, in_decl);
	    }
	  else
	    expanded = tsubst_template_args (ARGUMENT_PACK_ARGS (op),
					     args, complain, in_decl);
	  --cp_unevaluated_operand;
	  --c_inhibit_evaluation_warnings;

	  if (TREE_CODE (expanded) == TREE_VEC)
	    {
	      len = TREE_VEC_LENGTH (expanded);
	      /* Set TREE_USED for the benefit of -Wunused.  */
	      for (int i = 0; i < len; i++)
		if (DECL_P (TREE_VEC_ELT (expanded, i)))
		  TREE_USED (TREE_VEC_ELT (expanded, i)) = true;
	    }

	  if (expanded == error_mark_node)
	    RETURN (error_mark_node);
	  else if (PACK_EXPANSION_P (expanded)
		   || (TREE_CODE (expanded) == TREE_VEC
		       && pack_expansion_args_count (expanded)))

	    {
	      if (PACK_EXPANSION_P (expanded))
		/* OK.  */;
	      else
		expanded = make_argument_pack (expanded);

	      if (TYPE_P (expanded))
		RETURN (cxx_sizeof_or_alignof_type (input_location,
						    expanded, SIZEOF_EXPR,
						    false,
						    complain & tf_error));
	      else
		RETURN (cxx_sizeof_or_alignof_expr (input_location,
						    expanded, SIZEOF_EXPR,
						    false,
						    complain & tf_error));
	    }
	  else
	    RETURN (build_int_cst (size_type_node, len));
	}
      /* Fall through */

    case ALIGNOF_EXPR:
      {
	tree r;

	op1 = TREE_OPERAND (t, 0);
	if (TREE_CODE (t) == SIZEOF_EXPR && SIZEOF_EXPR_TYPE_P (t))
	  op1 = TREE_TYPE (op1);
	bool std_alignof = (TREE_CODE (t) == ALIGNOF_EXPR
			    && ALIGNOF_EXPR_STD_P (t));
        if (!args)
	  {
	    /* When there are no ARGS, we are trying to evaluate a
	       non-dependent expression from the parser.  Trying to do
	       the substitutions may not work.  */
	    if (!TYPE_P (op1))
	      op1 = TREE_TYPE (op1);
	  }
	else
	  {
	    ++cp_unevaluated_operand;
	    ++c_inhibit_evaluation_warnings;
	    if (TYPE_P (op1))
	      op1 = tsubst (op1, args, complain, in_decl);
	    else
	      op1 = tsubst_expr (op1, args, complain, in_decl);
	    --cp_unevaluated_operand;
	    --c_inhibit_evaluation_warnings;
	  }
        if (TYPE_P (op1))
	  r = cxx_sizeof_or_alignof_type (input_location,
					  op1, TREE_CODE (t), std_alignof,
					  complain & tf_error);
	else
	  r = cxx_sizeof_or_alignof_expr (input_location,
					  op1, TREE_CODE (t), std_alignof,
					  complain & tf_error);
	if (TREE_CODE (t) == SIZEOF_EXPR && r != error_mark_node)
	  {
	    if (TREE_CODE (r) != SIZEOF_EXPR || TYPE_P (op1))
	      {
		if (!processing_template_decl && TYPE_P (op1))
		  {
		    r = build_min (SIZEOF_EXPR, size_type_node,
				   build1 (NOP_EXPR, op1, error_mark_node));
		    SIZEOF_EXPR_TYPE_P (r) = 1;
		  }
		else
		  r = build_min (SIZEOF_EXPR, size_type_node, op1);
		TREE_SIDE_EFFECTS (r) = 0;
		TREE_READONLY (r) = 1;
	      }
	    SET_EXPR_LOCATION (r, EXPR_LOCATION (t));
	    copy_warning (r, t);
	  }
	RETURN (r);
      }

    case AT_ENCODE_EXPR:
      {
	op1 = TREE_OPERAND (t, 0);
	++cp_unevaluated_operand;
	++c_inhibit_evaluation_warnings;
	op1 = tsubst (op1, args, complain, in_decl);
	--cp_unevaluated_operand;
	--c_inhibit_evaluation_warnings;
	RETURN (objc_build_encode_expr (op1));
      }

    case NOEXCEPT_EXPR:
      op1 = TREE_OPERAND (t, 0);
      ++cp_unevaluated_operand;
      ++c_inhibit_evaluation_warnings;
      ++cp_noexcept_operand;
      op1 = tsubst_expr (op1, args, complain, in_decl);
      --cp_unevaluated_operand;
      --c_inhibit_evaluation_warnings;
      --cp_noexcept_operand;
      RETURN (finish_noexcept_expr (op1, complain));

    case MODOP_EXPR:
      {
	warning_sentinel s(warn_div_by_zero);
	tree lhs = RECUR (TREE_OPERAND (t, 0));
	tree rhs = RECUR (TREE_OPERAND (t, 2));

	tree r = build_x_modify_expr
	  (EXPR_LOCATION (t), lhs, TREE_CODE (TREE_OPERAND (t, 1)), rhs,
	   templated_operator_saved_lookups (t),
	   complain|decltype_flag);
	/* TREE_NO_WARNING must be set if either the expression was
	   parenthesized or it uses an operator such as >>= rather
	   than plain assignment.  In the former case, it was already
	   set and must be copied.  In the latter case,
	   build_x_modify_expr sets it and it must not be reset
	   here.  */
	if (warning_suppressed_p (t, OPT_Wparentheses))
	  suppress_warning (STRIP_REFERENCE_REF (r), OPT_Wparentheses);

	RETURN (r);
      }

    case ARROW_EXPR:
      op1 = tsubst_non_call_postfix_expression (TREE_OPERAND (t, 0),
						args, complain, in_decl);
      /* Remember that there was a reference to this entity.  */
      if (DECL_P (op1)
	  && !mark_used (op1, complain) && !(complain & tf_error))
	RETURN (error_mark_node);
      RETURN (build_x_arrow (input_location, op1, complain));

    case NEW_EXPR:
      {
	tree placement = RECUR (TREE_OPERAND (t, 0));
	tree init = RECUR (TREE_OPERAND (t, 3));
	vec<tree, va_gc> *placement_vec;
	vec<tree, va_gc> *init_vec;
	tree ret;
	location_t loc = EXPR_LOCATION (t);

	if (placement == NULL_TREE)
	  placement_vec = NULL;
	else if (placement == error_mark_node)
	  RETURN (error_mark_node);
	else
	  {
	    placement_vec = make_tree_vector ();
	    for (; placement != NULL_TREE; placement = TREE_CHAIN (placement))
	      vec_safe_push (placement_vec, TREE_VALUE (placement));
	  }

	/* If there was an initializer in the original tree, but it
	   instantiated to an empty list, then we should pass a
	   non-NULL empty vector to tell build_new that it was an
	   empty initializer() rather than no initializer.  This can
	   only happen when the initializer is a pack expansion whose
	   parameter packs are of length zero.  */
	if (init == NULL_TREE && TREE_OPERAND (t, 3) == NULL_TREE)
	  init_vec = NULL;
	else if (init == error_mark_node)
	  RETURN (error_mark_node);
	else
	  {
	    init_vec = make_tree_vector ();
	    if (init == void_node)
	      gcc_assert (init_vec != NULL);
	    else
	      {
		for (; init != NULL_TREE; init = TREE_CHAIN (init))
		  vec_safe_push (init_vec, TREE_VALUE (init));
	      }
	  }

	/* Avoid passing an enclosing decl to valid_array_size_p.  */
	in_decl = NULL_TREE;

	tree op1 = tsubst (TREE_OPERAND (t, 1), args, complain, in_decl);
	tree op2 = RECUR (TREE_OPERAND (t, 2));
	ret = build_new (loc, &placement_vec, op1, op2,
			 &init_vec, NEW_EXPR_USE_GLOBAL (t),
			 complain);

	if (placement_vec != NULL)
	  release_tree_vector (placement_vec);
	if (init_vec != NULL)
	  release_tree_vector (init_vec);

	RETURN (ret);
      }

    case DELETE_EXPR:
      {
	tree op0 = RECUR (TREE_OPERAND (t, 0));
	tree op1 = RECUR (TREE_OPERAND (t, 1));
	RETURN (delete_sanity (input_location, op0, op1,
			       DELETE_EXPR_USE_VEC (t),
			       DELETE_EXPR_USE_GLOBAL (t),
			       complain));
      }

    case COMPOUND_EXPR:
      {
	tree op0 = tsubst_expr (TREE_OPERAND (t, 0), args,
				complain & ~tf_decltype, in_decl);
	RETURN (build_x_compound_expr (EXPR_LOCATION (t),
				       op0,
				       RECUR (TREE_OPERAND (t, 1)),
				       templated_operator_saved_lookups (t),
				       complain|decltype_flag));
      }

    case CALL_EXPR:
      {
	tree function;
	unsigned int nargs;
	bool qualified_p;
	bool koenig_p;
	tree ret;

	function = CALL_EXPR_FN (t);
	/* Internal function with no arguments.  */
	if (function == NULL_TREE && call_expr_nargs (t) == 0)
	  RETURN (t);

	/* When we parsed the expression, we determined whether or
	   not Koenig lookup should be performed.  */
	koenig_p = KOENIG_LOOKUP_P (t);
	if (function == NULL_TREE)
	  {
	    koenig_p = false;
	    qualified_p = false;
	  }
	else if (TREE_CODE (function) == SCOPE_REF)
	  {
	    qualified_p = true;
	    function = tsubst_qualified_id (function, args, complain, in_decl,
					    /*done=*/false,
					    /*address_p=*/false);
	  }
	else if (CALL_EXPR_STATIC_CHAIN (t)
		 && TREE_CODE (function) == FUNCTION_DECL
		 && fndecl_built_in_p (function, BUILT_IN_CLASSIFY_TYPE))
	  {
	    tree type = tsubst (CALL_EXPR_STATIC_CHAIN (t), args, complain,
				in_decl);
	    if (dependent_type_p (type))
	      {
		ret = build_vl_exp (CALL_EXPR, 4);
		CALL_EXPR_FN (ret) = function;
		CALL_EXPR_STATIC_CHAIN (ret) = type;
		CALL_EXPR_ARG (ret, 0)
		  = build_min (SIZEOF_EXPR, size_type_node, type);
		TREE_TYPE (ret) = integer_type_node;
	      }
	    else
	      ret = build_int_cst (integer_type_node, type_to_class (type));
	    RETURN (ret);
	  }
	else if (koenig_p
		 && (identifier_p (function)
		     || (TREE_CODE (function) == TEMPLATE_ID_EXPR
			 && identifier_p (TREE_OPERAND (function, 0)))))
	  {
	    /* Do nothing; calling tsubst_expr on an identifier
	       would incorrectly perform unqualified lookup again.

	       Note that we can also have an IDENTIFIER_NODE if the earlier
	       unqualified lookup found a dependent local extern declaration
	       (as per finish_call_expr); in that case koenig_p will be false
	       and we do want to do the lookup again to find the substituted
	       declaration.  */
	    qualified_p = false;

	    if (TREE_CODE (function) == TEMPLATE_ID_EXPR)
	      function = tsubst_name (function, args, complain, in_decl);
	  }
	else
	  {
	    if (TREE_CODE (function) == COMPONENT_REF)
	      {
		tree op = TREE_OPERAND (function, 1);

		qualified_p = (TREE_CODE (op) == SCOPE_REF
			       || (BASELINK_P (op)
				   && BASELINK_QUALIFIED_P (op)));
	      }
	    else
	      qualified_p = false;

	    if (TREE_CODE (function) == ADDR_EXPR
		&& TREE_CODE (TREE_OPERAND (function, 0)) == FUNCTION_DECL)
	      /* Avoid error about taking the address of a constructor.  */
	      function = TREE_OPERAND (function, 0);

	    function = tsubst_expr (function, args, complain, in_decl);

	    if (BASELINK_P (function))
	      qualified_p = true;
	  }

	nargs = call_expr_nargs (t);
	releasing_vec call_args;
	tsubst_call_args (t, args, complain, in_decl, call_args);

	/* Stripped-down processing for a call in a thunk.  Specifically, in
	   the thunk template for a generic lambda.  */
	if (call_from_lambda_thunk_p (t))
	  {
	    /* Now that we've expanded any packs, the number of call args
	       might be different.  */
	    unsigned int cargs = call_args->length ();
	    tree thisarg = NULL_TREE;
	    if (TREE_CODE (function) == COMPONENT_REF)
	      {
		thisarg = TREE_OPERAND (function, 0);
		if (TREE_CODE (thisarg) == INDIRECT_REF)
		  thisarg = TREE_OPERAND (thisarg, 0);
		function = TREE_OPERAND (function, 1);
		if (TREE_CODE (function) == BASELINK)
		  function = BASELINK_FUNCTIONS (function);
	      }
	    /* We aren't going to do normal overload resolution, so force the
	       template-id to resolve.  */
	    function = resolve_nondeduced_context (function, complain);
	    for (unsigned i = 0; i < cargs; ++i)
	      {
		/* In a thunk, pass through args directly, without any
		   conversions.  */
		tree arg = (*call_args)[i];
		while (TREE_CODE (arg) != PARM_DECL)
		  arg = TREE_OPERAND (arg, 0);
		(*call_args)[i] = arg;
	      }
	    if (thisarg)
	      {
		/* If there are no other args, just push 'this'.  */
		if (cargs == 0)
		  vec_safe_push (call_args, thisarg);
		else
		  {
		    /* Otherwise, shift the other args over to make room.  */
		    tree last = (*call_args)[cargs - 1];
		    vec_safe_push (call_args, last);
		    for (int i = cargs - 1; i > 0; --i)
		      (*call_args)[i] = (*call_args)[i - 1];
		    (*call_args)[0] = thisarg;
		  }
	      }
	    ret = build_call_a (function, call_args->length (),
				call_args->address ());
	    /* The thunk location is not interesting.  */
	    SET_EXPR_LOCATION (ret, UNKNOWN_LOCATION);
	    CALL_FROM_THUNK_P (ret) = true;
	    if (CLASS_TYPE_P (TREE_TYPE (ret)))
	      CALL_EXPR_RETURN_SLOT_OPT (ret) = true;

	    RETURN (ret);
	  }

	/* We do not perform argument-dependent lookup if normal
	   lookup finds a non-function, in accordance with the
	   resolution of DR 218.  */
	if (koenig_p
	    && ((is_overloaded_fn (function)
		 /* If lookup found a member function, the Koenig lookup is
		    not appropriate, even if an unqualified-name was used
		    to denote the function.  */
		 && !DECL_FUNCTION_MEMBER_P (get_first_fn (function)))
		|| identifier_p (function)
		/* C++20 P0846: Lookup found nothing.  */
		|| (TREE_CODE (function) == TEMPLATE_ID_EXPR
		    && identifier_p (TREE_OPERAND (function, 0))))
	    /* Only do this when substitution turns a dependent call
	       into a non-dependent call.  */
	    && type_dependent_expression_p_push (t)
	    && !any_type_dependent_arguments_p (call_args))
	  function = perform_koenig_lookup (function, call_args, tf_none);

	if (function != NULL_TREE
	    && (identifier_p (function)
		|| (TREE_CODE (function) == TEMPLATE_ID_EXPR
		    && identifier_p (TREE_OPERAND (function, 0))
		    && !any_dependent_template_arguments_p (TREE_OPERAND
							    (function, 1))))
	    && !any_type_dependent_arguments_p (call_args))
	  {
	    bool template_id_p = (TREE_CODE (function) == TEMPLATE_ID_EXPR);
	    if (template_id_p)
	      function = TREE_OPERAND (function, 0);
	    if (koenig_p && (complain & tf_warning_or_error))
	      {
		/* For backwards compatibility and good diagnostics, try
		   the unqualified lookup again if we aren't in SFINAE
		   context.  */
		tree unq = tsubst_expr (function, args, complain, in_decl);
		if (unq == error_mark_node)
		  RETURN (error_mark_node);

		if (unq != function)
		  {
		    auto_diagnostic_group d;
		    char const *const msg
		      = G_("%qD was not declared in this scope, "
			   "and no declarations were found by "
			   "argument-dependent lookup at the point "
			   "of instantiation");

		    bool in_lambda = (current_class_type
				      && LAMBDA_TYPE_P (current_class_type));
		    /* In a lambda fn, we have to be careful to not
		       introduce new this captures.  Legacy code can't
		       be using lambdas anyway, so it's ok to be
		       stricter.  Be strict with C++20 template-id ADL too.
		       And be strict if we're already failing anyway.  */
		    bool strict = in_lambda || template_id_p || seen_error ();
		    bool diag = true;
		    if (strict)
		      error_at (cp_expr_loc_or_input_loc (t),
				msg, function);
		    else
		      diag = permerror (cp_expr_loc_or_input_loc (t),
					msg, function);
		    if (diag)
		      {
			tree fn = unq;

			if (INDIRECT_REF_P (fn))
			  fn = TREE_OPERAND (fn, 0);
			if (is_overloaded_fn (fn))
			  fn = get_first_fn (fn);

			if (!DECL_P (fn))
			  /* Can't say anything more.  */;
			else if (DECL_CLASS_SCOPE_P (fn))
			  {
			    location_t loc = cp_expr_loc_or_input_loc (t);
			    inform (loc,
				    "declarations in dependent base %qT are "
				    "not found by unqualified lookup",
				    DECL_CLASS_CONTEXT (fn));
			    if (current_class_ptr)
			      inform (loc,
				      "use %<this->%D%> instead", function);
			    else
			      inform (loc,
				      "use %<%T::%D%> instead",
				      current_class_name, function);
			  }
			else
			  inform (DECL_SOURCE_LOCATION (fn),
				  "%qD declared here, later in the "
				  "translation unit", fn);
			if (strict)
			  RETURN (error_mark_node);
		      }

		    function = unq;
		  }
	      }
	    if (identifier_p (function))
	      {
		if (complain & tf_error)
		  unqualified_name_lookup_error (function);
		RETURN (error_mark_node);
	      }
	  }

	/* Remember that there was a reference to this entity.  */
	if (function != NULL_TREE
	    && DECL_P (function)
	    && !mark_used (function, complain) && !(complain & tf_error))
	  RETURN (error_mark_node);

	if (!maybe_fold_fn_template_args (function, complain))
	  return error_mark_node;

	/* Put back tf_decltype for the actual call.  */
	complain |= decltype_flag;

	if (function == NULL_TREE)
	  switch (CALL_EXPR_IFN (t))
	    {
	    case IFN_LAUNDER:
	      gcc_assert (nargs == 1);
	      if (vec_safe_length (call_args) != 1)
		{
		  error_at (cp_expr_loc_or_input_loc (t),
			    "wrong number of arguments to "
			    "%<__builtin_launder%>");
		  ret = error_mark_node;
		}
	      else
		ret = finish_builtin_launder (cp_expr_loc_or_input_loc (t),
					      (*call_args)[0], complain);
	      break;

	    case IFN_VEC_CONVERT:
	      gcc_assert (nargs == 1);
	      if (vec_safe_length (call_args) != 1)
		{
		  error_at (cp_expr_loc_or_input_loc (t),
			    "wrong number of arguments to "
			    "%<__builtin_convertvector%>");
		  ret = error_mark_node;
		  break;
		}
	      ret = cp_build_vec_convert ((*call_args)[0], input_location,
					  tsubst (TREE_TYPE (t), args,
						  complain, in_decl),
					  complain);
	      if (TREE_CODE (ret) == VIEW_CONVERT_EXPR)
		RETURN (ret);
	      break;

	    case IFN_SHUFFLEVECTOR:
	      {
		ret = build_x_shufflevector (input_location, call_args,
					     complain);
		if (ret != error_mark_node)
		  RETURN (ret);
		break;
	      }

	    case IFN_ASSUME:
	      gcc_assert (nargs == 1);
	      if (vec_safe_length (call_args) != 1)
		{
		  error_at (cp_expr_loc_or_input_loc (t),
			    "wrong number of arguments to "
			    "%<assume%> attribute");
		  ret = error_mark_node;
		}
	      else
		{
		  tree &arg = (*call_args)[0];
		  if (!type_dependent_expression_p (arg))
		    arg = contextual_conv_bool (arg, tf_warning_or_error);
		  if (error_operand_p (arg))
		    {
		      ret = error_mark_node;
		      break;
		    }
		  ret = build_assume_call (EXPR_LOCATION (t), arg);
		  RETURN (ret);
		}
	      break;

	    case IFN_GOMP_DISPATCH:
	      ret = build_call_expr_internal_loc (EXPR_LOCATION (t),
						  IFN_GOMP_DISPATCH,
						  TREE_TYPE (call_args[0]), 1,
						  call_args[0]);
	      RETURN (ret);
	      break;

	    default:
	      /* Unsupported internal function with arguments.  */
	      gcc_unreachable ();
	    }
	else if (TREE_CODE (function) == OFFSET_REF
		 || TREE_CODE (function) == DOTSTAR_EXPR
		 || TREE_CODE (function) == MEMBER_REF)
	  ret = build_offset_ref_call_from_tree (function, &call_args,
						 complain);
	else if (concept_check_p (function))
	  /* Calls to concepts should have been previously diagnosed.  */
	  gcc_assert (false);
	else
	  ret = finish_call_expr (function, &call_args,
				  /*disallow_virtual=*/qualified_p,
				  koenig_p,
				  complain);

	if (ret != error_mark_node)
	  {
	    bool op = CALL_EXPR_OPERATOR_SYNTAX (t);
	    bool ord = CALL_EXPR_ORDERED_ARGS (t);
	    bool rev = CALL_EXPR_REVERSE_ARGS (t);
	    bool mtc = false;
	    if (TREE_CODE (t) == CALL_EXPR)
	      mtc = CALL_EXPR_MUST_TAIL_CALL (t);
	    if (op || ord || rev || mtc)
	      if (tree call = extract_call_expr (ret))
		{
		  CALL_EXPR_OPERATOR_SYNTAX (call) = op;
		  CALL_EXPR_ORDERED_ARGS (call) = ord;
		  CALL_EXPR_REVERSE_ARGS (call) = rev;
		  if (TREE_CODE (call) == CALL_EXPR)
		    CALL_EXPR_MUST_TAIL_CALL (call) = mtc;
		  else if (TREE_CODE (call) == AGGR_INIT_EXPR)
		    AGGR_INIT_EXPR_MUST_TAIL (call) = mtc;
		}
	    if (CALL_FROM_NEW_OR_DELETE_P (t))
	      {
		tree call = extract_call_expr (ret);
		tree fn = cp_get_callee_fndecl_nofold (call);
		if (fn ? !DECL_IS_REPLACEABLE_OPERATOR (fn)
		       : !processing_template_decl)
		  {
		    auto_diagnostic_group d;
		    location_t loc = cp_expr_loc_or_input_loc (t);
		    if (!fn || IDENTIFIER_NEW_OP_P (DECL_NAME (fn)))
		      error_at (loc, "call to %<__builtin_operator_new%> "
				     "does not select replaceable global "
				     "allocation function");
		    else 
		      error_at (loc, "call to %<__builtin_operator_delete%> "
				     "does not select replaceable global "
				     "deallocation function");
		    if (fn)
		      inform (DECL_SOURCE_LOCATION (fn),
			      "selected function declared here");
		  }
		else if (call && TREE_CODE (call) == CALL_EXPR)
		  CALL_FROM_NEW_OR_DELETE_P (call) = 1;
	      }
	    if (warning_suppressed_p (t, OPT_Wpessimizing_move))
	      /* This also suppresses -Wredundant-move.  */
	      suppress_warning (ret, OPT_Wpessimizing_move);
	  }

	RETURN (ret);
      }

    case COND_EXPR:
      {
	tree cond = RECUR (TREE_OPERAND (t, 0));
	cond = mark_rvalue_use (cond);
	tree folded_cond = fold_non_dependent_expr (cond, complain);
	tree exp1, exp2;

	if (TREE_CODE (folded_cond) == INTEGER_CST)
	  {
	    if (integer_zerop (folded_cond))
	      {
		++c_inhibit_evaluation_warnings;
		exp1 = RECUR (TREE_OPERAND (t, 1));
		--c_inhibit_evaluation_warnings;
		exp2 = RECUR (TREE_OPERAND (t, 2));
	      }
	    else
	      {
		exp1 = RECUR (TREE_OPERAND (t, 1));
		++c_inhibit_evaluation_warnings;
		exp2 = RECUR (TREE_OPERAND (t, 2));
		--c_inhibit_evaluation_warnings;
	      }
	    cond = folded_cond;
	  }
	else
	  {
	    exp1 = RECUR (TREE_OPERAND (t, 1));
	    exp2 = RECUR (TREE_OPERAND (t, 2));
	  }

	warning_sentinel s(warn_duplicated_branches);
	RETURN (build_x_conditional_expr (EXPR_LOCATION (t),
					 cond, exp1, exp2, complain));
      }

    case PSEUDO_DTOR_EXPR:
      {
	tree op0 = RECUR (TREE_OPERAND (t, 0));
	tree op1 = RECUR (TREE_OPERAND (t, 1));
	tree op2 = tsubst (TREE_OPERAND (t, 2), args, complain, in_decl);
	RETURN (finish_pseudo_destructor_expr (op0, op1, op2,
					       input_location, complain));
      }

    case TREE_LIST:
      RETURN (tsubst_tree_list (t, args, complain, in_decl));

    case COMPONENT_REF:
      {
	tree object;
	tree object_type;
	tree member;
	tree r;

	object = tsubst_non_call_postfix_expression (TREE_OPERAND (t, 0),
						     args, complain, in_decl);
	/* Remember that there was a reference to this entity.  */
	if (DECL_P (object)
	    && !mark_used (object, complain) && !(complain & tf_error))
	  RETURN (error_mark_node);
	object_type = TREE_TYPE (object);

	member = TREE_OPERAND (t, 1);
	if (BASELINK_P (member))
	  member = tsubst_baselink (member,
				    non_reference (TREE_TYPE (object)),
				    args, complain, in_decl);
	else
	  member = tsubst_name (member, args, complain, in_decl);
	if (member == error_mark_node)
	  RETURN (error_mark_node);

	if (object_type && TYPE_PTRMEMFUNC_P (object_type)
	    && TREE_CODE (member) == FIELD_DECL)
	  {
	    r = build_ptrmemfunc_access_expr (object, DECL_NAME (member));
	    RETURN (r);
	  }
	else if (TREE_CODE (member) == FIELD_DECL)
	  {
	    r = finish_non_static_data_member (member, object, NULL_TREE,
					       complain);
	    if (REF_PARENTHESIZED_P (t))
	      r = force_paren_expr (r);
	    RETURN (r);
	  }
	else if (type_dependent_expression_p (object))
	  /* We can't do much here.  */;
	else if (!CLASS_TYPE_P (object_type))
	  {
	    if (scalarish_type_p (object_type))
	      {
		tree s = NULL_TREE;
		tree dtor = member;

		if (TREE_CODE (dtor) == SCOPE_REF)
		  {
		    s = TREE_OPERAND (dtor, 0);
		    dtor = TREE_OPERAND (dtor, 1);
		  }
		if (TREE_CODE (dtor) == BIT_NOT_EXPR)
		  {
		    dtor = TREE_OPERAND (dtor, 0);
		    if (TYPE_P (dtor))
		      RETURN (finish_pseudo_destructor_expr
			      (object, s, dtor, input_location, complain));
		  }
	      }
	  }
	else if (TREE_CODE (member) == SCOPE_REF
		 && TREE_CODE (TREE_OPERAND (member, 1)) == TEMPLATE_ID_EXPR)
	  {
	    /* Lookup the template functions now that we know what the
	       scope is.  */
	    tree scope = TREE_OPERAND (member, 0);
	    tree tmpl = TREE_OPERAND (TREE_OPERAND (member, 1), 0);
	    tree args = TREE_OPERAND (TREE_OPERAND (member, 1), 1);
	    member = lookup_qualified_name (scope, tmpl, LOOK_want::NORMAL,
					    /*complain=*/false);
	    if (BASELINK_P (member))
	      {
		BASELINK_FUNCTIONS (member)
		  = build_nt (TEMPLATE_ID_EXPR, BASELINK_FUNCTIONS (member),
			      args);
		member = (adjust_result_of_qualified_name_lookup
			  (member, BINFO_TYPE (BASELINK_BINFO (member)),
			   object_type));
	      }
	    else
	      {
		qualified_name_lookup_error (scope, tmpl, member,
					     input_location);
		RETURN (error_mark_node);
	      }
	  }
	else if (TREE_CODE (member) == SCOPE_REF
		 && !CLASS_TYPE_P (TREE_OPERAND (member, 0))
		 && TREE_CODE (TREE_OPERAND (member, 0)) != NAMESPACE_DECL)
	  {
	    if (complain & tf_error)
	      {
		if (TYPE_P (TREE_OPERAND (member, 0)))
		  error ("%qT is not a class or namespace",
			 TREE_OPERAND (member, 0));
		else
		  error ("%qD is not a class or namespace",
			 TREE_OPERAND (member, 0));
	      }
	    RETURN (error_mark_node);
	  }

	r = finish_class_member_access_expr (object, member,
					     /*template_p=*/false,
					     complain);
	if (REF_PARENTHESIZED_P (t))
	  r = force_paren_expr (r);
	RETURN (r);
      }

    case THROW_EXPR:
      RETURN (build_throw
       (input_location, RECUR (TREE_OPERAND (t, 0)), complain));

    case CONSTRUCTOR:
      {
	vec<constructor_elt, va_gc> *n;
	constructor_elt *ce;
	unsigned HOST_WIDE_INT idx;
	bool process_index_p;
        int newlen;
        bool need_copy_p = false;
	tree r;

	tsubst_flags_t tcomplain = complain;
	if (COMPOUND_LITERAL_P (t))
	  tcomplain |= tf_tst_ok;
	tree type = tsubst (TREE_TYPE (t), args, tcomplain, in_decl);
	if (type == error_mark_node)
	  RETURN (error_mark_node);

	/* We do not want to process the index of aggregate
	   initializers as they are identifier nodes which will be
	   looked up by digest_init.  */
	process_index_p = !(type && MAYBE_CLASS_TYPE_P (type));

	if (null_member_pointer_value_p (t))
	  {
	    gcc_assert (same_type_p (type, TREE_TYPE (t)));
	    RETURN (t);
	  }

	n = vec_safe_copy (CONSTRUCTOR_ELTS (t));
        newlen = vec_safe_length (n);
	FOR_EACH_VEC_SAFE_ELT (n, idx, ce)
	  {
	    if (ce->index && process_index_p
		/* An identifier index is looked up in the type
		   being initialized, not the current scope.  */
		&& TREE_CODE (ce->index) != IDENTIFIER_NODE)
	      ce->index = RECUR (ce->index);

            if (PACK_EXPANSION_P (ce->value))
              {
                /* Substitute into the pack expansion.  */
                ce->value = tsubst_pack_expansion (ce->value, args, complain,
                                                  in_decl);

		if (ce->value == error_mark_node
		    || PACK_EXPANSION_P (ce->value))
		  ;
		else if (TREE_VEC_LENGTH (ce->value) == 1)
                  /* Just move the argument into place.  */
                  ce->value = TREE_VEC_ELT (ce->value, 0);
                else
                  {
                    /* Update the length of the final CONSTRUCTOR
                       arguments vector, and note that we will need to
                       copy.*/
                    newlen = newlen + TREE_VEC_LENGTH (ce->value) - 1;
                    need_copy_p = true;
                  }
              }
            else
              ce->value = RECUR (ce->value);
	  }

        if (need_copy_p)
          {
            vec<constructor_elt, va_gc> *old_n = n;

            vec_alloc (n, newlen);
            FOR_EACH_VEC_ELT (*old_n, idx, ce)
              {
                if (TREE_CODE (ce->value) == TREE_VEC)
                  {
                    int i, len = TREE_VEC_LENGTH (ce->value);
                    for (i = 0; i < len; ++i)
                      CONSTRUCTOR_APPEND_ELT (n, 0,
                                              TREE_VEC_ELT (ce->value, i));
                  }
                else
                  CONSTRUCTOR_APPEND_ELT (n, 0, ce->value);
              }
          }

	r = build_constructor (init_list_type_node, n);
	CONSTRUCTOR_IS_DIRECT_INIT (r) = CONSTRUCTOR_IS_DIRECT_INIT (t);
	CONSTRUCTOR_IS_DESIGNATED_INIT (r)
	  = CONSTRUCTOR_IS_DESIGNATED_INIT (t);

	if (TREE_HAS_CONSTRUCTOR (t))
	  {
	    fcl_t cl = fcl_functional;
	    if (CONSTRUCTOR_C99_COMPOUND_LITERAL (t))
	      cl = fcl_c99;
	    RETURN (finish_compound_literal (type, r, complain, cl));
	  }

	TREE_TYPE (r) = type;
	RETURN (r);
      }

    case TYPEID_EXPR:
      {
	tree operand_0 = TREE_OPERAND (t, 0);
	if (TYPE_P (operand_0))
	  {
	    operand_0 = tsubst (operand_0, args, complain, in_decl);
	    RETURN (get_typeid (operand_0, complain));
	  }
	else
	  {
	    operand_0 = RECUR (operand_0);
	    RETURN (build_typeid (operand_0, complain));
	  }
      }

    case FUNCTION_DECL:
    case PARM_DECL:
    case VAR_DECL:
      if (!args)
	RETURN (t);
      tree r;
      if (VAR_OR_FUNCTION_DECL_P (t)
	  && DECL_LANG_SPECIFIC (t) && DECL_TEMPLATE_INFO (t))
	r = tsubst_decl (t, args, complain);
      else if (VAR_OR_FUNCTION_DECL_P (t) && DECL_LOCAL_DECL_P (t))
	{
	  /* Local specialization will usually have been created when
	     we instantiated the DECL_EXPR_DECL. */
	  r = retrieve_local_specialization (t);
	  if (!r)
	    {
	      /* We're in a generic lambda referencing a local extern
		 from an outer block-scope of a non-template.  */
	      gcc_checking_assert (LAMBDA_FUNCTION_P (current_function_decl));
	      r = t;
	    }
	}
      else if (local_variable_p (t)
	       && ((r = retrieve_local_specialization (t))
		   || TREE_CODE (t) == PARM_DECL
		   || uses_template_parms (DECL_CONTEXT (t))))
	{
	  if (r == NULL_TREE && TREE_CODE (t) == PARM_DECL)
	    {
	      /* We get here for a use of 'this' in an NSDMI.  */
	      if (DECL_NAME (t) == this_identifier && current_class_ptr)
		RETURN (current_class_ptr);

	      /* This can happen for a parameter name used later in a function
		 declaration (such as in a late-specified return type).  Just
		 make a dummy decl, since it's only used for its type.  */
	      gcc_assert (cp_unevaluated_operand);
	      r = tsubst_decl (t, args, complain);
	      /* Give it the template pattern as its context; its true context
		 hasn't been instantiated yet and this is good enough for
		 mangling.  */
	      DECL_CONTEXT (r) = DECL_CONTEXT (t);
	    }
	  else if (r == NULL_TREE)
	    {
	      /* First try name lookup to find the instantiation.  */
	      r = lookup_name (DECL_NAME (t));
	      if (r)
		{
		  if (!VAR_P (r))
		    {
		      /* During error-recovery we may find a non-variable,
			 even an OVERLOAD: just bail out and avoid ICEs and
			 duplicate diagnostics (c++/62207).  */
		      gcc_assert (seen_error ());
		      RETURN (error_mark_node);
		    }
		  if (!is_capture_proxy (r))
		    {
		      /* Make sure the one we found is the one we want.  */
		      tree ctx = enclosing_instantiation_of (DECL_CONTEXT (t));
		      if (ctx != DECL_CONTEXT (r))
			r = NULL_TREE;
		    }
		}

	      if (r)
		/* OK */;
	      else
		{
		  /* This can happen for a variable used in a
		     late-specified return type of a local lambda, or for a
		     local static or constant.  Building a new VAR_DECL
		     should be OK in all those cases.  */
		  r = tsubst_decl (t, args, complain);
		  if (local_specializations)
		    /* Avoid infinite recursion (79640).  */
		    register_local_specialization (r, t);
		  if (decl_maybe_constant_var_p (r))
		    {
		      /* We can't call cp_finish_decl, so handle the
			 initializer by hand.  */
		      tree init = tsubst_init (DECL_INITIAL (t), r, args,
					       complain, in_decl);
		      if (!processing_template_decl)
			init = maybe_constant_init (init);
		      if (processing_template_decl
			  ? potential_constant_expression (init)
			  : reduced_constant_expression_p (init))
			DECL_INITIALIZED_BY_CONSTANT_EXPRESSION_P (r)
			  = TREE_CONSTANT (r) = true;
		      DECL_INITIAL (r) = init;
		      if (tree auto_node = type_uses_auto (TREE_TYPE (r)))
			TREE_TYPE (r)
			  = do_auto_deduction (TREE_TYPE (r), init, auto_node,
					       complain, adc_variable_type);
		    }
		  gcc_assert (cp_unevaluated_operand
			      || processing_contract_condition
			      || TREE_STATIC (r)
			      || decl_constant_var_p (r)
			      || seen_error ());
		  if (!processing_template_decl
		      && !TREE_STATIC (r))
		    r = process_outer_var_ref (r, complain);
		}
	      /* Remember this for subsequent uses.  */
	      if (local_specializations)
		register_local_specialization (r, t);
	    }
	  if (TREE_CODE (r) == ARGUMENT_PACK_SELECT)
	    r = argument_pack_select_arg (r);
	}
      else
	r = t;
      if (!mark_used (r, complain))
	RETURN (error_mark_node);

      if (!no_name_lookup_flag
	  && (TREE_CODE (t) == PARM_DECL || TREE_CODE (t) == VAR_DECL))
	{
	  /* ??? We're doing a subset of finish_id_expression here.  */
	  if (tree wrap = maybe_get_tls_wrapper_call (r))
	    /* Replace an evaluated use of the thread_local variable with
	       a call to its wrapper.  */
	    r = wrap;
	  else if (outer_automatic_var_p (r))
	    r = process_outer_var_ref (r, complain);

	  if (!TYPE_REF_P (TREE_TYPE (t)))
	    /* If the original type was a reference, we'll be wrapped in
	       the appropriate INDIRECT_REF.  */
	    r = convert_from_reference (r);
	}
      RETURN (r);

    case CONST_DECL:
      {
	tree enum_type;
	tree v;

	if (DECL_TEMPLATE_PARM_P (t))
	  RETURN (RECUR (DECL_INITIAL (t)));
	if (!args || !uses_template_parms (DECL_CONTEXT (t)))
	  RETURN (t);

	/* Unfortunately, we cannot just call lookup_name here.
	   Consider:

	     template <int I> int f() {
	     enum E { a = I };
	     struct S { void g() { E e = a; } };
	     };

	   When we instantiate f<7>::S::g(), say, lookup_name is not
	   clever enough to find f<7>::a.  */
	enum_type = tsubst (DECL_CONTEXT (t), args, complain, in_decl);

	for (v = TYPE_VALUES (enum_type);
	     v != NULL_TREE;
	     v = TREE_CHAIN (v))
	  if (TREE_PURPOSE (v) == DECL_NAME (t))
	    RETURN (TREE_VALUE (v));

	  /* We didn't find the name.  That should never happen; if
	     name-lookup found it during preliminary parsing, we
	     should find it again here during instantiation.  */
	gcc_unreachable ();
	RETURN (t);
      }

    case FIELD_DECL:
      if (DECL_CONTEXT (t))
	{
	  tree ctx;

	  ctx = tsubst_entering_scope (DECL_CONTEXT (t), args,
